@prefix rdf:   <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs:  <http://www.w3.org/2000/01/rdf-schema#> .
@prefix ex:    <http://example.org/tio-instance/FS-EVSLA-03/> .

ex:intent a icm:Intent, evsla:EnterpriseVpnSlaIntent ;
  icm:intentElements ex:exp-bandwidth, ex:cond-bandwidth, ex:topology ;
  rdfs:comment "Assure minimum guaranteed bandwidth to a specific spoke for 宏達物流 enterprise VPN."@en .
ex:tenant a evsla:Tenant ; rdfs:label "宏達物流"@zh .
ex:service a evsla:EnterpriseVpnService ; evsla:forTenant ex:tenant .
ex:exp-bandwidth a icm:PropertyExpectation, evsla:SlaExpectation ;
  icm:target ex:tgt-bandwidth ;
  rdfs:comment "Guaranteed bandwidth must be at least 100 Mbps to the named spoke."@en .
ex:tgt-bandwidth a icm:Target ;
  evsla:hasMetric evsla:guaranteedBandwidth ;
  icm:valuesOfTargetProperty ex:thr-bandwidth ;
  evsla:hasThreshold ex:thr-bandwidth ;
  evsla:hasStatistic evsla:minimum ;
  evsla:hasScope evsla:specificSpoke ;
  evsla:hasMeasurementMethod evsla:activeMeasurement ;
  evsla:hasTimeWindow evsla:fiveMinuteWindow .
ex:thr-bandwidth a quan:Quantity ; rdf:value 100 ; quan:unit "Mbps" .
ex:cond-bandwidth a log:Condition ;
  quan:atLeast ( ex:obs-bandwidth-value ex:thr-bandwidth ) .
ex:obs-bandwidth a met:Observation ; met:observedMetric evsla:guaranteedBandwidth .
ex:obs-bandwidth-value a quan:Quantity ; met:observedValue ( ex:obs-bandwidth ) .
ex:topology a icm:Context, evsla:HubAndSpokeTopology ;
  evsla:hasHub [ a evsla:HubSite ; rdfs:label "台北營運總部"@zh ] ;
  evsla:hasSpoke [ a evsla:SpokeSite ; rdfs:label "高雄倉儲中心"@zh ] .

